steps.command:
cat > /etc/bind/named.conf.options << 'EOF'
options {
    directory "/var/cache/bind";
    recursion yes;
    forwarders {
        8.8.8.8;
        8.8.4.4;
        1.1.1.1;
    };
    forward first;
    dnssec-validation no;
    listen-on-v6 { any; };
    allow-query { any; };
};
EOF
